import {socialButtons} from "./social-auth.js";
import {S} from './state.js';
import {icon,esc,num,money,dateISO,dateLabel,clock,duration,avatar,brand,btn,iconBtn,empty,field,select,textarea,badge,progress,ring,stat,pageHead,chart} from './ui.js';

export const nav=[['home','home','Início'],['workouts','dumbbell','Meus treinos'],['library','book','Exercícios'],['evolution','chart','Evolução'],['agenda','calendar','Agenda'],['nutrition','food','Nutrição'],['achievements','trophy','Conquistas']];
export const extraNav=[['wallet','qr','Acesso à academia'],['plans','wallet','Meu plano'],['units','building','Unidades'],['profile','user','Meu perfil']];
const allNav=[...nav,...extraNav,['notifications','bell','Notificações'],['assistant','spark','Assistente ATHEV'],['trainer','users','Área do professor'],['admin','shield','Administração'],['session','dumbbell','Treino em andamento']];
export const goals=['Hipertrofia','Emagrecimento','Ganho de força','Condicionamento','Saúde','Definição','Outro'];
export const levels=['Iniciante','Intermediário','Avançado'];
export const muscles=['Todos','Peito','Costas','Ombro','Bíceps','Tríceps','Pernas','Glúteos','Panturrilha','Abdômen','Cardio'];
export const measureNames={weight:'Peso',height:'Altura',fat:'Gordura corporal',arm:'Braço',forearm:'Antebraço',chest:'Peitoral',waist:'Cintura',abdomen:'Abdômen',hip:'Quadril',thigh:'Coxa',calf:'Panturrilha'};
export const isManager=()=>['ADMIN','GERENTE'].includes(S.user?.role);
export const isTrainer=()=>['PROFESSOR','ADMIN','GERENTE'].includes(S.user?.role);
const currentWorkout=()=>S.data.workouts.find(w=>w.day===new Date().getDay()-1)||S.data.workouts[0];
const sectionHead=(title,action='')=>`<div class="card-head"><h2>${title}</h2>${action}</div>`;
const navLink=([route,ico,label])=>`<a href="#${route}" class="nav-item ${S.route===route?'active':''}">${icon(ico)}<span>${label}</span></a>`;

export function authView(){
 if(S.auth==='welcome'&&!window.matchMedia('(max-width: 700px)').matches)S.auth='login';
 if(S.auth==='welcome')return `<div class="auth"><section class="auth-panel welcome-mobile" id="main"><img class="welcome-bg" src="assets/hero.png" alt=""><div class="welcome-brand"><img src="assets/logo.png" alt="ATHEV"></div><div class="welcome-copy"><h2>Sua Melhor Versão<br>É Inegociável</h2><div class="welcome-divider"></div><p>A arena te espera. Forja teu corpo e mente com disciplina inabalável.</p></div><div class="welcome-actions"><button class="btn btn-primary btn-block" data-action="register">VAMOS COMEÇAR</button><span>Já tem uma conta? <button class="btn btn-ghost" data-action="auth-login">Fazer login</button></span></div></section></div>`;
 let content='';
 if(S.auth==='register')content=`<div class="eyebrow">O PRIMEIRO PASSO É SEU</div><h2 class="auth-title">Crie sua conta.</h2><p class="auth-description">Um novo capítulo na sua evolução.</p><form id="register-form">${field('Nome completo','name','','text','required maxlength="80" autocomplete="name"')}${field('E-mail','email','','email','required autocomplete="email"')}${field('Senha · mínimo 8 caracteres, letras e números','password','','password','required minlength="8" maxlength="128" autocomplete="new-password"')}<div class="form-row">${field('Data de nascimento','birth_date','','date','required max="'+dateISO()+'"')}${select('Sexo (opcional)','sex',['','Feminino','Masculino','Outro','Prefiro não informar'])}</div><div class="form-row">${field('Altura (cm)','height','','number','required min="60" max="250" step="0.1"')}${field('Peso (kg)','weight','','number','required min="20" max="500" step="0.1"')}</div><div class="form-row">${select('Seu objetivo','goal',goals,'Hipertrofia')}${select('Experiência','level',levels)}</div><label class="check"><input type="checkbox" name="consent" required> Li e aceito os termos e a política de privacidade.</label><button class="btn btn-ghost btn-small" type="button" data-action="legal">Ler termos e privacidade</button><p class="form-error" role="alert"></p><button class="btn btn-primary btn-block auth-submit">CRIAR CONTA ${icon('arrow')}</button></form>${socialButtons()}<div class="auth-bottom">Já faz parte? <button class="btn btn-ghost" data-action="auth-login">Entrar</button></div>`;
 else if(S.auth==='recover')content=`<div class="eyebrow">RETOME SUA JORNADA</div><h2 class="auth-title">Recuperar acesso.</h2><p class="auth-description">Receba um link no seu e-mail para redefinir a senha.</p><form id="recover-form">${field('E-mail','email','','email','required')}<p class="form-error" role="alert"></p><button class="btn btn-primary btn-block">ENVIAR LINK ${icon('arrow')}</button></form><div class="auth-bottom"><button class="btn btn-ghost" data-action="auth-login">Voltar para o login</button></div>`;
 else if(S.auth==='reset-password')content=`<h2 class="auth-title">Defina sua nova senha.</h2><form id="reset-password-form">${field('Nova senha','password','','password','required minlength="8" autocomplete="new-password"')}<p class="form-error" role="alert"></p><button class="btn btn-primary btn-block">SALVAR SENHA</button></form>`;
 else content=`<div class="eyebrow">BEM-VINDO AO SEU PRÓXIMO NÍVEL</div><h2 class="auth-title">Sua jornada começa aqui.</h2><p class="auth-description">Entre na sua conta e continue sua evolução.</p><form id="login-form">${field('E-mail','email','','email','placeholder="voce@exemplo.com" required autocomplete="username"')}<label class="field"><span>Senha</span><div class="password-wrap"><input class="input" name="password" type="password" placeholder="Sua senha" required autocomplete="current-password"><button type="button" data-action="toggle-password" aria-label="Mostrar ou ocultar senha">${icon('eye')}</button></div></label><div class="between"><label class="check"><input type="checkbox" name="remember" checked> Manter conectado</label><button class="btn btn-ghost btn-small" type="button" data-action="recover">Esqueci minha senha</button></div><p class="form-error" role="alert"></p><button class="btn btn-primary btn-block auth-submit">ENTRAR ${icon('arrow')}</button></form>${socialButtons()}<div class="auth-bottom">Ainda não tem uma conta? <button class="btn btn-ghost" data-action="register">Cadastre-se</button></div>`;
 return `<div class="auth"><section class="auth-story"><img src="assets/hero.png" alt="Atletas ATHEV em uma academia preta e dourada"><div class="story-top"><span>O SEU PRÓXIMO NÍVEL.</span><span>EST. 2026</span></div><div class="story-copy"><div class="story-line"></div><h1 class="display">Sua melhor versão<br>é <span>inegociável.</span></h1><p>Cada repetição conta. Cada escolha transforma.<br>Construa a sua evolução, todos os dias.</p><div class="eyebrow">TRAIN · EVOLVE · CONQUER</div></div></section><section class="auth-panel" id="main"><div class="auth-inner"><div class="auth-brand">${brand()}</div>${content}<div class="auth-footer">ATHEV © 2026 · DISCIPLINA QUE TRANSFORMA</div></div></section></div>`;
}

export function shell(content){
 const user=S.data.user,unread=S.data.notifications.some(n=>!n.read);
 const management=[...(isTrainer()?[['trainer','users','Área do professor']]:[]),...(['RECEPCIONISTA','GERENTE','ADMIN'].includes(S.user.role)?[['admin','shield',S.user.role==='RECEPCIONISTA'?'Recepção':'Administração']]:[])];
 return `<aside class="sidebar">${brand()}<div class="nav-label">SUA JORNADA</div><nav class="side-nav">${nav.map(navLink).join('')}</nav><div class="side-divider"></div><div class="nav-label">SUA ACADEMIA</div><nav class="side-nav">${extraNav.slice(0,2).map(navLink).join('')}${management.map(navLink).join('')}</nav><div class="sidebar-bottom"><div class="side-motto">${icon('spark')}<p>DISCIPLINA HOJE.<br><strong>CONQUISTA AMANHÃ.</strong></p></div><a href="#profile" class="side-user">${avatar(user)}<div><strong>${esc(user.name)}</strong><small>${esc(user.role==='ALUNO'?'Membro ATHEV':user.role)}</small></div></a><div class="sidebar-footer">TRAIN · EVOLVE · CONQUER</div></div></aside><div class="app-body"><header class="topbar"><div class="breadcrumb">Sua jornada ${icon('right')} <b>${allNav.find(x=>x[0]===S.route)?.[2]||'Início'}</b></div><a class="mobile-brand" href="#home" aria-label="ATHEV — Início">${brand()}</a><div class="top-actions"><span class="date-label">${new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'})}</span><span class="env-label">ATHEV</span><a class="icon-btn" href="#assistant" title="Assistente ATHEV" aria-label="Assistente ATHEV">${icon('spark')}</a><a class="icon-btn" href="#notifications" title="Notificações" aria-label="Notificações">${icon('bell')}${unread?'<span class="dot"></span>':''}</a><a href="#profile">${avatar(user)}</a></div></header><main class="main" id="main" tabindex="-1">${content}<footer class="app-footer"><span>ATHEV · SUA MELHOR VERSÃO É INEGOCIÁVEL.</span><span>TRAIN · EVOLVE · CONQUER</span></footer></main></div><nav class="bottom-nav" aria-label="Navegação principal">${[['home','home','Início'],['workouts','dumbbell','Treino'],['evolution','chart','Evolução'],['agenda','calendar','Agenda'],['profile','user','Perfil']].map(([r,i,l])=>`<a href="#${r}" class="${S.route===r?'active':''}">${icon(i)}<span>${l}</span></a>`).join('')}</nav>`;
}

function home(){
 const d=S.data,s=d.stats,w=currentWorkout(),next=d.workouts[(d.workouts.indexOf(w)+1)%Math.max(1,d.workouts.length)],cl=d.classes.find(c=>c.booked&&new Date(c.starts_at)>new Date());
 const weekStart=new Date();weekStart.setDate(weekStart.getDate()-((weekStart.getDay()+6)%7));
 const days=Array.from({length:7},(_,i)=>{const dt=new Date(weekStart);dt.setDate(dt.getDate()+i);return {label:['S','T','Q','Q','S','S','D'][i],date:dateISO(dt)};});
 const weight=d.measurements.filter(m=>m.weight).map(m=>({date:m.date,value:m.weight}));
 return `<div class="page-head"><div><div class="greeting-date">MAIS UM DIA PARA EVOLUIR</div><h1>Olá, ${esc(d.user.name.split(' ')[0])}<span class="gold">.</span></h1><p>Seu único adversário é quem você foi ontem.</p></div><a class="btn btn-secondary btn-small" href="#wallet">${icon('qr')}Meu acesso</a></div><div class="dashboard-grid"><div><section class="hero-card"><img src="assets/athlete.png" alt="Atleta ATHEV se preparando para treinar"><div class="hero-content"><span class="hero-badge">${icon('dumbbell')} SEU PRÓXIMO NÍVEL COMEÇA AQUI</span><h2 class="display">TREINE COM PROPÓSITO.<br><em>EVOLUA SEM LIMITES.</em></h2><p>${w?esc(w.muscle)+' · '+w.items.length+' exercícios · '+w.duration+' minutos':'Monte sua primeira ficha e comece sua jornada.'}</p>${d.active?btn('CONTINUAR TREINO','resume','','primary','play'):w?btn('INICIAR TREINO','start',w.id,'primary','play'):btn('CRIAR MEU TREINO','workout-new','','primary','plus')}</div><span class="hero-mark">ATHEV PERFORMANCE</span></section><div class="grid grid-4 stat-cards">${stat('Treinos na semana',s.week,'/ 4','dumbbell',`<span class="gold">${Math.round(Math.min(s.week/4,1)*100)}%</span> da meta semanal`)}${stat('Sequência atual',s.streak,'dias','flame','Cada dia ativo conta')}${stat('Peso atual',d.user.weight?num(d.user.weight,1):'—','kg','weight','Último registro corporal')}${stat('Recordes pessoais',s.records,'','trophy','Exercícios com melhor carga')}</div><section class="card">${sectionHead('Seu treino de hoje',`<a class="btn btn-ghost btn-small gold" href="#workouts">Ver todos ${icon('right')}</a>`)}${w?`<div class="workout-preview"><div class="workout-letter">${esc(w.name.replace('Treino ', '').slice(0,1))}</div><div><h3>${esc(w.muscle)}</h3><small>${esc(w.name)} · ${esc(w.level)} · ${w.duration} min</small></div><span class="badge badge-gold" style="margin-left:auto">${w.items.length} exercícios</span></div>${w.items.slice(0,3).map((e,i)=>`<div class="exercise-row"><span class="exercise-index">${String(i+1).padStart(2,'0')}</span><div class="exercise-info"><strong>${esc(e.name)}</strong><small>${esc(e.equipment)}</small></div><span class="exercise-reps">${e.sets} × ${e.reps}</span>${iconBtn('right','exercise',e.exercise_id,'Ver execução')}</div>`).join('')}<div class="between section-gap"><small>Próximo: <span class="gold">${esc(next?.muscle||'Defina sua próxima ficha')}</span></small>${btn('Ver ficha','workout-detail',w.id,'secondary','dumbbell')}</div>`:empty('Sua primeira ficha','Crie um treino ou solicite uma ficha ao professor.','dumbbell')}</section><div class="quick-links">${[['library','book','Exercícios'],['nutrition','food','Minha nutrição'],['agenda','calendar','Reservar aula'],['assistant','spark','Assistente ATHEV']].map(([r,i,l])=>`<a class="quick-link" href="#${r}">${icon(i)}${l}</a>`).join('')}</div></div><aside class="stack dashboard-aside"><section class="card">${sectionHead('Disciplina semanal',icon('target'))}<div class="weekly-ring">${ring(Math.round(Math.min(s.week/4,1)*100)+'%','DA META SEMANAL',s.week/4*100)}</div><p class="tiny muted" style="text-align:center;margin-bottom:0">${s.week} de 4 treinos concluídos</p><div class="week-dots">${days.map(x=>`<div>${x.label}<div class="week-dot ${s.frequency.some(f=>f.date===x.date)?'done':x.date===dateISO()?'today':''}">${s.frequency.some(f=>f.date===x.date)?'✓':Number(x.date.slice(-2))}</div></div>`).join('')}</div></section><section class="card">${sectionHead('Sua evolução',`<a href="#evolution" class="gold">${icon('right')}</a>`)}<p class="card-subtitle">Peso corporal · últimos registros</p><div class="chart-summary">${weight.length?num(weight.at(-1).value,1):'—'} <small>kg</small></div>${chart(weight.slice(-8))}</section><section class="card">${sectionHead('Próxima aula',icon('calendar'))}${cl?`<div class="mini-class"><div class="time-box">${cl.starts_at.slice(11,16)}<small>${dateLabel(cl.starts_at)}</small></div><div><strong>${esc(cl.title)}</strong><br><small>${esc(cl.teacher)} · ${cl.duration} min</small><br><span class="badge badge-green" style="margin-top:6px">Reserva confirmada</span></div></div>`:`<p class="tiny muted">Escolha uma aula e adicione movimento à sua semana.</p><a href="#agenda" class="btn btn-secondary btn-small">Explorar aulas ${icon('arrow')}</a>`}</section><div class="quote-card">${icon('flame')}<div><p>A constância constrói o extraordinário.</p><small>O PROCESSO É A SUA CONQUISTA.</small></div></div></aside></div>`;
}

function workouts(){
 const d=S.data;return pageHead('DISCIPLINA EM CADA REPETIÇÃO','Meus treinos','Sua rotina. Seu ritmo. Sua próxima conquista.',btn('Criar treino','workout-new','','primary','plus'))+(d.active?`<div class="notice between" style="margin-bottom:22px"><span>Você tem um treino em andamento: <strong>${esc(d.active.name)}</strong></span>${btn('Continuar','resume','','primary','play')}</div>`:'')+`<div class="grid grid-3">${d.workouts.map(w=>workoutCard(w)).join('')}</div>`+(!d.workouts.length?empty('Sua rotina começa aqui','Crie uma ficha ou peça ao professor para montar seu treino.','dumbbell'):'');
}
export function workoutCard(w,staff=false){return `<article class="card workout-card"><div class="card-tools">${iconBtn('copy','workout-copy',w.id,'Duplicar ficha')}${iconBtn('edit','workout-edit',w.id,'Editar ficha')}${iconBtn('trash','workout-delete',w.id,'Excluir ficha')}</div><div class="workout-letter">${esc(w.name.replace('Treino ','').slice(0,1))}</div><div class="eyebrow">${esc(w.name)}</div><h2>${esc(w.muscle)}</h2><small>${esc(w.level)} · ${['Segunda','Terça','Quarta','Quinta','Sexta','Sábado','Domingo'][w.day]}</small><div class="workout-meta"><span>${icon('dumbbell')}${w.items.length} exercícios</span><span>${icon('clock')}${w.duration} min</span><span>${icon('activity')}${w.items.reduce((a,e)=>a+e.sets,0)} séries</span></div><p class="tiny muted">${w.items.slice(0,3).map(e=>esc(e.name)).join(' · ')}${w.items.length>3?'…':''}</p><div class="row wrap">${!staff?btn('Iniciar treino','start',w.id,'primary','play'):''}${btn('Ver ficha','workout-detail',w.id,'secondary','right')}</div></article>`;}

function library(){
 const list=S.data.exercises.filter(e=>(S.filter==='Todos'||(S.filter==='Favoritos'?S.data.favorites.includes(e.id):e.muscle===S.filter))&&normalize(e.name+' '+e.equipment).includes(normalize(S.search)));
 return pageHead('CONHEÇA CADA MOVIMENTO','Biblioteca de exercícios',`${S.data.exercises.length} exercícios. Técnica antes de carga.`)+`<div class="toolbar"><div class="search-box">${icon('search')}<input class="input" data-search="library" value="${esc(S.search)}" placeholder="Buscar exercício ou equipamento" aria-label="Buscar exercício"></div>${btn('Favoritos','filter','Favoritos',S.filter==='Favoritos'?'primary':'secondary','star')}</div><div class="chips">${muscles.map(m=>`<button class="chip ${S.filter===m?'active':''}" data-action="filter" data-id="${m}">${m}</button>`).join('')}</div><div class="grid grid-3 exercise-library">${list.map(e=>`<article class="card exercise-card"><div class="exercise-visual"><img src="assets/gym.png" alt="Academia ATHEV · imagem ilustrativa" loading="lazy"><div class="muscle-letter">${esc(e.muscle)}</div><button class="icon-btn ${S.data.favorites.includes(e.id)?'active':''}" data-action="favorite" data-id="${e.id}" aria-label="${S.data.favorites.includes(e.id)?'Remover dos':'Adicionar aos'} favoritos">${icon('star')}</button></div><div class="exercise-card-body"><h3>${esc(e.name)}</h3><small>${esc(e.equipment)}</small><button class="btn btn-secondary btn-block" data-action="exercise" data-id="${e.id}">Ver execução ${icon('right')}</button></div></article>`).join('')}</div>${!list.length?empty('Nenhum exercício encontrado','Tente outro nome ou grupo muscular.','search'):''}`;
}
export const normalize=s=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');

function session(){
 const s=S.data.active;if(!s)return pageHead('TREINO','Pronto para começar?','Escolha sua ficha e inicie uma sessão.')+`<a href="#workouts" class="btn btn-primary">Ver meus treinos ${icon('arrow')}</a>`;
 const elapsed=Math.max(0,Math.floor((Date.now()-new Date(s.started_at).getTime())/1000)),done=s.items.flatMap(e=>e.sets).filter(x=>x.done).length,total=s.items.flatMap(e=>e.sets).length;
 return `<div class="session-head"><div><div class="eyebrow" style="margin-bottom:5px">FOCO NO AGORA</div><h2 style="margin:0">${esc(s.name)}</h2></div><div class="session-clock" id="session-clock">${clock(elapsed)}</div>${btn('Finalizar','finish-open','','primary','check')}</div><div class="session-layout"><div>${s.items.map((e,ei)=>`<section class="card session-exercise" data-ex="${ei}"><div class="card-head"><div><span class="eyebrow">EXERCÍCIO ${String(ei+1).padStart(2,'0')}</span><h3 style="margin:5px 0">${esc(e.name)}</h3><small>${esc(e.muscle)} · ${e.rest}s descanso · ${esc(e.technique)}</small></div><div class="row gap6">${iconBtn('play','exercise',e.exercise_id,'Ver execução')}${iconBtn('copy','substitute',ei,'Substituir exercício')}</div></div><small>Carga anterior: <span class="gold">${num(e.previous_weight??e.sets[0].weight,1)} kg</span></small><div class="set-head"><span>Série</span><span style="text-align:center">Carga (kg)</span><span style="text-align:center">Repetições</span><span>OK</span><span></span></div>${e.sets.map((set,si)=>`<div class="set-row ${set.done?'done':''}"><span class="set-number">${si+1}</span><input type="number" class="input" min="0" max="1500" step="0.5" value="${set.weight}" data-set="weight" data-ex="${ei}" data-series="${si}" aria-label="Carga da série ${si+1} de ${esc(e.name)}"><input type="number" class="input" min="1" max="1000" step="1" value="${set.reps}" data-set="reps" data-ex="${ei}" data-series="${si}" aria-label="Repetições da série ${si+1} de ${esc(e.name)}"><button class="set-check" data-action="set-check" data-id="${ei}:${si}" aria-label="${set.done?'Desmarcar':'Concluir'} série ${si+1}">${icon(set.done?'check':'plus')}</button><button class="set-remove" data-action="set-remove" data-id="${ei}:${si}" aria-label="Remover série ${si+1}">${icon('close')}</button></div>`).join('')}<button class="btn btn-ghost btn-small gold" data-action="set-add" data-id="${ei}">${icon('plus')}Adicionar série</button><textarea class="note-input" data-ex-note="${ei}" placeholder="Observação deste exercício" aria-label="Observação de ${esc(e.name)}">${esc(e.notes)}</textarea></section>`).join('')}<div class="card"><h3>Como foi o treino?</h3><textarea id="session-notes" placeholder="Anote como se sentiu, ajustes de carga ou observações." aria-label="Observações do treino">${esc(s.notes)}</textarea><div class="between section-gap">${btn('Descartar treino','discard','','danger','trash')}${btn('Finalizar treino','finish-open','','primary','check')}</div></div></div><aside class="card rest-card"><div><div class="eyebrow">RECUPERE O FÔLEGO</div><h3>Seu descanso</h3></div><div class="rest-clock" id="rest-clock">${clock(Math.max(0,Math.ceil(s.rest_until-Date.now()/1000)))}</div><p class="rest-desc" id="rest-desc">O próximo passo também começa na pausa.</p>${progress(done,total)}${btn('Pular descanso','skip-rest','','secondary','arrow')}<div class="session-summary"><strong class="gold">${done} / ${total}</strong><p style="margin-top:5px">séries concluídas</p><small>Carga × repetições realizadas</small><h3 style="margin-top:10px">${num(s.items.flatMap(e=>e.sets).reduce((a,x)=>a+(x.done?x.weight*x.reps:0),0))} kg</h3></div></aside></div>`;
}

const sincePeriod=()=>{const dt=new Date();dt.setDate(dt.getDate()-(S.period||36500));return dateISO(dt);};
function evolution(){
 const d=S.data,st=d.stats,period=sincePeriod(),history=d.history.filter(h=>h.started_at.slice(0,10)>=period),ms=d.measurements.filter(m=>m.date>=period);
 const metrics=Object.entries(measureNames).map(([k,v])=>[k,v]);
 const periodTabs=`<div class="tabs date-range">${[[7,'7 dias'],[30,'30 dias'],[90,'3 meses'],[180,'6 meses'],[365,'1 ano'],[0,'Tudo']].map(([n,l])=>`<button class="tab ${S.period===n?'active':''}" data-action="period" data-id="${n}">${l}</button>`).join('')}</div>`;
 let content='';
 if(S.evolutionTab==='corpo'){
 const points=ms.filter(m=>m[S.metric]!=null).map(m=>({date:m.date,value:m[S.metric]})),unit=S.metric==='weight'?'kg':S.metric==='fat'?'%':'cm';
 content=`<div class="card">${sectionHead('Evolução corporal',`<select class="metric-select" id="measure-metric" aria-label="Medida do gráfico">${metrics.map(([k,v])=>`<option value="${k}" ${S.metric===k?'selected':''}>${v}</option>`).join('')}</select>`)}<div class="chart-summary">${points.length?num(points.at(-1).value,1):'—'} <small>${unit}</small></div>${chart(points,unit)}</div><h2 class="section-title">Seus registros</h2><div class="card"><div class="table-wrap"><table><thead><tr><th>Data</th>${metrics.map(([,v])=>`<th>${v}</th>`).join('')}</tr></thead><tbody>${[...ms].reverse().map(m=>`<tr><td>${dateLabel(m.date)}</td>${metrics.map(([k])=>`<td>${m[k]!=null?num(m[k],1):'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${!ms.length?empty('Sem medidas neste período','Registre suas medidas para acompanhar as mudanças.','weight'):''}</div>`;
 }else if(S.evolutionTab==='historico')content=`<div class="card">${history.map(h=>`<div class="history-row"><div class="workout-letter">${esc(h.name.replace('Treino ','')[0])}</div><div class="exercise-info"><strong>${esc(h.name)}</strong><small>${dateLabel(h.started_at)} · ${duration(h.duration)} · ${h.summary.sets} séries · ${num(h.summary.volume)} kg</small></div>${badge(h.difficulty||'Concluído','green')}${btn('Resumo','history',h.id,'secondary','right')}</div>`).join('')||empty('Seu histórico começa no primeiro treino','Conclua uma sessão para vê-la aqui.','dumbbell')}</div>`;
 else if(S.evolutionTab==='fotos')content=`<div class="notice" style="margin-bottom:20px">Suas fotos ficam no banco do ATHEV, protegidas pelo login. Escolha dois registros para comparar a evolução.</div><div class="card"><div class="photo-pair">${['before','after'].map((slot,i)=>`<div><label class="field"><span>${i?'Depois':'Antes'}</span><select data-photo-slot="${slot}" aria-label="Foto ${i?'depois':'antes'}"><option value="">Selecione um registro</option>${d.photos.map(p=>`<option value="${p.id}">${dateLabel(p.date)} · ${esc(p.angle)}</option>`).join('')}</select></label><div class="photo-frame" id="photo-${slot}"><span class="muted tiny">Selecione uma foto</span></div></div>`).join('')}</div><div class="section-gap">${btn('Adicionar foto','photo-new','','primary','upload')}</div></div><div class="card section-gap">${sectionHead('Registros fotográficos')}${d.photos.map(p=>`<div class="between settings-row"><span>${dateLabel(p.date)} · ${esc(p.angle)}</span>${iconBtn('trash','photo-delete',p.id,'Excluir foto')}</div>`).join('')||empty('Nenhuma foto adicionada','Frente, lado ou costas. Compare sempre condições semelhantes.','user')}</div>`;
 else if(S.evolutionTab==='carga'){
 const eid=(S.loadExercise||d.records[0]?.exercise_id||d.exercises[0]?.id),ex=d.exercises.find(x=>x.id===eid),points=[...history].reverse().flatMap(h=>{const sets=h.items.filter(e=>e.exercise_id===eid).flatMap(e=>e.sets).filter(s=>s.done);return sets.length?[{date:h.started_at.slice(0,10),value:Math.max(...sets.map(x=>x.weight))}]:[];});
 content=`<div class="card">${sectionHead('Progressão de carga',`<select id="load-exercise" class="metric-select" aria-label="Exercício para progressão">${d.exercises.map(e=>`<option value="${e.id}" ${e.id===eid?'selected':''}>${esc(e.name)}</option>`).join('')}</select>`)}<p class="card-subtitle">Maior carga por sessão · ${esc(ex?.name||'')}</p>${chart(points)}<div class="table-wrap"><table><thead><tr><th>Data</th><th>Maior carga</th></tr></thead><tbody>${[...points].reverse().map(p=>`<tr><td>${dateLabel(p.date)}</td><td>${num(p.value,1)} kg</td></tr>`).join('')}</tbody></table></div></div>`;
 }else{
 const volume=history.reduce((a,h)=>a+h.summary.volume,0),time=history.reduce((a,h)=>a+h.duration,0),weights=ms.filter(m=>m.weight).map(m=>({date:m.date,value:m.weight}));
 const frequency=[];const from=new Date();from.setDate(from.getDate()-27);for(let i=0;i<4;i++){let start=new Date(from),end=new Date(from);start.setDate(start.getDate()+i*7);end.setDate(end.getDate()+i*7+7);frequency.push({date:dateISO(start),value:d.history.filter(h=>h.started_at>=dateISO(start)&&h.started_at<dateISO(end)).length});}
 content=`<div class="grid grid-4 stat-cards">${stat('Treinos no período',history.length,'','dumbbell','Sessões concluídas')}${stat('Tempo treinado',duration(time),'','clock','Tempo total registrado')}${stat('Volume acumulado',num(volume),'kg','weight','Carga × repetições')}${stat('Exercícios realizados',history.reduce((a,h)=>a+h.summary.exercises,0),'','activity','No período selecionado')}</div><div class="grid grid-2"><div class="card">${sectionHead('Volume de treino')}<p class="card-subtitle">Volume total de cada sessão</p>${chart([...history].reverse().map(h=>({date:h.started_at.slice(0,10),value:h.summary.volume})))}</div><div class="card">${sectionHead('Peso corporal')}<p class="card-subtitle">Seu corpo, sua evolução</p>${chart(weights)}</div><div class="card">${sectionHead('Frequência semanal')}<p class="card-subtitle">Últimas 4 semanas · treinos por intervalo de 7 dias</p>${chart(frequency,'treinos')}</div><div class="card">${sectionHead('Recordes pessoais',icon('trophy'))}${d.records.slice(0,5).map(r=>`<div class="exercise-row"><span class="exercise-index">${icon('trophy')}</span><div class="exercise-info"><strong>${esc(r.name)}</strong><small>${dateLabel(r.achieved_at)}</small></div><strong class="gold">${num(r.weight)} <small>kg</small></strong></div>`).join('')||empty('O primeiro recorde está por vir','Registre as cargas realizadas.','trophy')}</div></div>`;
 }
 return pageHead('CADA NÚMERO CONTA UMA HISTÓRIA','Sua evolução','Compare resultados. Reconheça o seu progresso.',btn('Registrar medidas','measurement-new','','primary','plus'))+`<div class="tabs">${[['geral','Geral'],['corpo','Corpo'],['carga','Carga'],['historico','Histórico'],['fotos','Fotos']].map(([k,l])=>`<button class="tab ${S.evolutionTab===k?'active':''}" data-action="evo-tab" data-id="${k}">${l}</button>`).join('')}</div>${S.evolutionTab!=='fotos'?periodTabs:''}${content}`;
}

function agenda(){
 const d=S.data,year=S.calendar.getFullYear(),month=S.calendar.getMonth(),first=new Date(year,month,1),start=new Date(first);start.setDate(1-(first.getDay()+6)%7);
 const items=[...d.events.map(e=>({...e,type:'event'})),...d.classes.filter(c=>c.booked).map(c=>({...c,type:'class'})),...d.history.map(h=>({id:h.id,title:'Treino concluído',starts_at:h.started_at,type:'workout'}))];
 let days=Array.from({length:42},(_,i)=>{let dt=new Date(start);dt.setDate(dt.getDate()+i);return dt;});
 if(S.calendarMode==='week'){const dt=S.selectedDate?new Date(S.selectedDate+'T12:00:00'):new Date();dt.setDate(dt.getDate()-(dt.getDay()+6)%7);days=Array.from({length:7},(_,i)=>{let x=new Date(dt);x.setDate(x.getDate()+i);return x;});}
 const classes=d.classes.filter(c=>new Date(c.starts_at)>new Date()&&(!S.selectedDate||c.starts_at.startsWith(S.selectedDate)));
 const events=d.events.filter(e=>!S.selectedDate||e.starts_at.startsWith(S.selectedDate));
 return pageHead('ORGANIZE SUA CONSTÂNCIA','Sua agenda','Reserve um tempo para a sua melhor versão.',btn('Agendar atividade','event-new','','primary','plus'))+`<div class="card"><div class="between wrap" style="margin-bottom:20px"><div class="calendar-nav">${iconBtn('left','calendar-prev','','Período anterior')}<h2>${S.calendar.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</h2>${iconBtn('right','calendar-next','','Próximo período')}</div><div class="row gap6">${btn(S.calendarMode==='month'?'Ver semana':'Ver mês','calendar-mode','','secondary','calendar')}${btn('Hoje','calendar-today','','ghost')}</div></div><div class="calendar">${['SEG','TER','QUA','QUI','SEX','SÁB','DOM'].map(x=>`<div class="calendar-weekday">${x}</div>`).join('')}${days.map(dt=>{let iso=dateISO(dt),evs=items.filter(e=>e.starts_at.startsWith(iso));return `<button class="calendar-day ${dt.getMonth()!==month?'outside':''} ${iso===dateISO()?'today':''} ${S.selectedDate===iso?'selected':''}" data-action="calendar-select" data-id="${iso}" aria-label="${dateLabel(iso,true)}, ${evs.length} atividades"><span>${dt.getDate()}</span>${evs.slice(0,2).map(e=>`<div class="calendar-event">${esc(e.title)}</div>`).join('')}${evs.length>2?`<small class="tiny">+${evs.length-2}</small>`:''}</button>`;}).join('')}</div></div><div class="between section-gap"><h2 class="section-title" style="margin:0">${S.selectedDate?dateLabel(S.selectedDate,true):'Próximas aulas'}</h2>${S.selectedDate?btn('Ver todas','calendar-clear','','ghost'):''}</div><div class="stack section-gap">${classes.map(c=>`<article class="card class-card"><div class="time-box">${c.starts_at.slice(11,16)}<small>${dateLabel(c.starts_at)}</small></div><div class="class-info"><h3>${esc(c.title)}</h3><small>${esc(c.teacher)} · ${c.duration} min</small><br><small>${esc(c.gym_name)} · ${Math.max(0,c.capacity-c.reserved)} vagas</small></div><div class="class-actions">${c.booked?badge('Reservada','green'):badge(c.capacity-c.reserved+' vagas','gold')}${btn(c.booked?'Cancelar reserva':'Reservar',c.booked?'cancel-reservation':'reserve',c.id,c.booked?'secondary':'primary',c.booked?'close':'plus')}<small class="tiny">Cancelamento: ${c.cancel_minutes} min antes</small></div></article>`).join('')||empty('Sem aulas neste período','Escolha outro dia ou consulte as próximas aulas.','calendar')}</div><h2 class="section-title">Atividades pessoais</h2><div class="card">${events.map(e=>`<div class="history-row"><div class="exercise-index">${icon(e.kind==='Descanso'?'heart':'calendar')}</div><div class="exercise-info"><strong>${esc(e.title)}</strong><small>${dateLabel(e.starts_at)} · ${e.starts_at.slice(11,16)} · ${esc(e.kind)}</small></div>${iconBtn('edit','event-edit',e.id,'Reagendar atividade')}${iconBtn('trash','event-delete',e.id,'Excluir atividade')}</div>`).join('')||empty('Tempo reservado para você','Agende um treino, descanso, avaliação ou consulta.','calendar')}</div>`;
}

function nutrition(){
 const logs=S.data.nutrition,go=S.data.user.nutrition_goals,tot={calories:0,protein:0,carbs:0,fat:0,water:0};logs.forEach(x=>Object.keys(tot).forEach(k=>tot[k]+=x[k]||0));
 return pageHead('ENERGIA PARA EVOLUIR','Minha nutrição','Seu diário alimentar e sua hidratação de hoje.',btn('Registrar refeição','food-new','','primary','plus'))+`<div class="nutrition-top"><div class="card"><div class="calorie-main"><div><div class="eyebrow">CALORIAS DE HOJE</div><div class="calorie-value">${num(tot.calories)} <small>/ ${num(go.calories)} kcal</small></div><p class="card-subtitle">${dateLabel(dateISO(),true)}</p></div>${ring(Math.round(tot.calories/go.calories*100)+'%','DA META',tot.calories/go.calories*100)}</div><div class="macros">${[['protein','Proteínas'],['carbs','Carboidratos'],['fat','Gorduras']].map(([k,l])=>`<div class="macro"><p class="tiny muted" style="margin-bottom:6px">${l}</p><strong>${num(tot[k])} <small>/ ${num(go[k])} g</small></strong>${progress(tot[k],go[k])}</div>`).join('')}</div></div><div class="card">${sectionHead('Hidratação',icon('water'))}<div class="water-value gold">${num(tot.water/1000,2)} <small>/ ${num(go.water/1000,1)} L</small></div>${progress(tot.water,go.water)}<div class="water-actions section-gap">${[250,500,750].map(n=>btn('+'+n+' ml','water',n,'secondary','plus')).join('')}</div></div></div><div class="between section-gap"><h2 class="section-title" style="margin:0">Refeições registradas</h2>${btn('Ajustar metas','nutrition-goals','','ghost','settings')}</div><div class="card section-gap">${logs.filter(l=>!l.water).map(l=>`<div class="food-row"><div class="food-symbol">${icon('food')}</div><div class="exercise-info"><strong>${esc(l.meal)}</strong><small>${esc(l.food)}</small><br><small>P ${num(l.protein)}g · C ${num(l.carbs)}g · G ${num(l.fat)}g</small></div><strong class="gold">${num(l.calories)} <small>kcal</small></strong>${iconBtn('trash','food-delete',l.id,'Excluir refeição')}</div>`).join('')||empty('Seu diário de hoje está vazio','Registre os alimentos e os valores da porção consumida.','food')}</div><div class="card section-gap">${sectionHead('Registros de água')}${logs.filter(l=>l.water).map(l=>`<div class="between settings-row"><span class="row">${icon('water')} ${num(l.water)} ml</span>${iconBtn('trash','food-delete',l.id,'Remover registro de água')}</div>`).join('')||'<p class="tiny muted">Use os botões de hidratação para registrar água.</p>'}</div><div class="notice section-gap">As metas iniciais são exemplos editáveis, sem prescrição individual. ${S.data.user.professional?`Profissional informado: <strong>${esc(S.data.user.professional)}</strong>.`:'Você pode vincular as metas ao profissional que acompanha sua alimentação.'}</div>`;
}

function achievements(){const d=S.data,s=d.stats;return pageHead('CONQUISTE O SEU LUGAR','Cada passo, uma conquista.','Sua disciplina é o que faz a diferença.')+`<div class="card xp-card"><div class="medal">${icon('trophy')}</div><div style="flex:1"><div class="eyebrow" style="margin-bottom:5px">ATHEV PERFORMANCE</div><h2 style="margin-bottom:13px">Nível ${s.level} · ${num(s.xp)} XP</h2>${progress(s.xp%1000,1000)}<p class="tiny muted" style="margin:8px 0 0">${num(1000-s.xp%1000)} XP para o próximo nível · 100 XP por treino + conquistas</p></div><div class="level-number">${String(s.level).padStart(2,'0')}</div></div><h2 class="section-title">Desafios em andamento</h2><div class="grid grid-2">${d.challenges.map(c=>`<div class="card challenge-card"><div class="between"><h3>${esc(c.title)}</h3>${icon('target')}</div><div class="progress-label"><span>${c.progress} / ${c.target}</span><strong class="gold">${Math.round(c.progress/c.target*100)}%</strong></div>${progress(c.progress,c.target)}</div>`).join('')}</div><h2 class="section-title">Suas medalhas</h2><div class="grid grid-2">${d.achievements.map(a=>`<div class="card achievement ${a.unlocked_at?'':'locked'}"><div class="medal">${icon(a.unlocked_at?'medal':'lock')}</div><div><h3>${esc(a.title)}</h3><p>${esc(a.description)}</p><small class="gold">${a.unlocked_at?'Desbloqueada · '+dateLabel(a.unlocked_at):'A conquistar'} · +${a.xp} XP</small></div></div>`).join('')}</div><p class="tiny muted section-gap">Sequências registram atividade; não são uma orientação para eliminar dias de descanso.</p>`;}

function wallet(){const d=S.data,m=d.membership,u=d.user;return pageHead('SUA JORNADA TEM ACESSO LIVRE','Carteira digital','Seu acesso, sempre com você.')+`<div class="grid grid-2"><div><div class="wallet"><div class="between">${brand()}${badge(m?.status||'Sem plano',m?.status==='Ativo'?'green':'red')}</div><div class="wallet-profile">${avatar(u)}<div><h2>${esc(u.name)}</h2><small>MATRÍCULA ATH-${String(u.id).padStart(6,'0')}</small></div></div><div class="wallet-details"><div><small>PLANO</small><br>${esc(m?.plan_name||'Não cadastrado')}</div><div><small>UNIDADE FAVORITA</small><br>${esc(m?.gym_name||'Não cadastrada')}</div></div></div><div class="qr-area card section-gap"><div id="qr-content"><div class="success-icon">${icon('qr')}</div><h3>Pronto para treinar?</h3><p class="tiny muted">Gere seu QR de uso único, válido por 60 segundos.</p>${btn('Gerar meu QR Code','qr-generate','','primary','qr')}</div></div></div><div class="stack"><section class="card">${sectionHead('Lotação da academia',icon('users'))}<h3 class="muted" style="font-size:21px">Dados indisponíveis</h3><p class="tiny muted">A unidade ainda não está conectada a uma fonte de ocupação em tempo real.</p></section><section class="card">${sectionHead('Histórico de acessos')}${d.checkins.map(c=>`<div class="settings-row"><div><strong>${dateLabel(c.created_at)} · ${c.created_at.slice(11,16)}</strong><small>Validação no sistema local</small></div>${badge('Demo','gold')}</div>`).join('')||empty('Nenhum acesso registrado','Um acesso aparece após a validação pela recepção.','qr')}</section><div class="notice">O código contém somente um token temporário. A recepção pode validá-lo no painel local. A catraca física depende de integração com o equipamento.</div></div></div>`;}

function plans(){const d=S.data,m=d.membership;return pageHead('INVISTA NA SUA MELHOR VERSÃO','Meu plano','Acompanhe seu plano e sua próxima mensalidade.')+`<div class="notice" style="margin-bottom:22px">Planos e faturas cadastrados pela administração. <strong>Nenhuma cobrança real é feita.</strong></div>${m?`<div class="card between wrap"><div><div class="eyebrow">PLANO ATUAL</div><h2>ATHEV ${esc(m.plan_name)}</h2><small>${esc(m.status)} · Próxima cobrança: ${dateLabel(m.next_billing,true)}</small></div><div><div class="chart-summary">${money(m.price)}<small> / mês</small></div><small>${esc(m.payment_method)}</small></div></div>`:''}<div class="grid grid-3 section-gap">${d.plans.map(p=>`<div class="card plan-card ${p.id===m?.plan_id?'current':''}">${p.id===m?.plan_id?'<span class="badge badge-gold plan-current">Seu plano</span>':''}<div class="plan-name">${esc(p.name)}</div><div class="plan-price">${money(p.price)}<small> / mês</small></div><ul class="benefits">${p.benefits.split('|').map(b=>`<li>${icon('check')}${esc(b)}</li>`).join('')}</ul>${p.id===m?.plan_id?badge('Plano atual','gold'):btn('Escolher plano','plan-change',p.id,'secondary','arrow')}</div>`).join('')}</div><div class="card section-gap">${sectionHead('Faturas e pagamentos',btn('Forma de pagamento','payment-method','','ghost','edit'))}<div class="table-wrap"><table><thead><tr><th>Fatura</th><th>Vencimento</th><th>Valor</th><th>Status</th><th>Ações</th></tr></thead><tbody>${d.payments.map(p=>`<tr><td>#ATH-${String(p.id).padStart(4,'0')}</td><td>${dateLabel(p.due_date)}</td><td>${money(p.amount)}</td><td>${badge(p.status,p.status==='Pago'?'green':'gold')}</td><td><div class="row gap6">${btn('Fatura','invoice',p.id,'ghost','receipt')}</div></td></tr>`).join('')}</tbody></table></div>${!d.payments.length?empty('Nenhuma fatura','As faturas cadastradas pela academia aparecerão aqui.','receipt'):''}</div><div class="card section-gap"><div class="between wrap"><div><h3>Cancelamento do plano</h3><small>${m?.cancel_requested?'Solicitação registrada para análise da administração.':'Solicite o cancelamento para análise da administração da unidade.'}</small></div>${btn(m?.cancel_requested?'Retirar solicitação':'Solicitar cancelamento','plan-cancel','','secondary')}</div></div>`;}

function units(){return pageHead('ENCONTRE O SEU ESPAÇO','Unidades ATHEV','Sua disciplina vai com você.')+`<div class="grid grid-2">${S.data.gyms.map(g=>`<article class="card exercise-card"><div class="exercise-visual" style="height:210px"><img src="assets/gym.png" alt="Academia ATHEV · imagem ilustrativa" loading="lazy"><div class="muscle-letter" style="font-size:26px">${esc(g.name)}</div></div><div class="exercise-card-body"><p class="tiny muted">${esc(g.address)}</p><p class="tiny">${esc(g.hours)}</p><p class="tiny muted">${esc(g.phone)}</p><p class="tiny"><span class="gold">Serviços</span><br>${esc(g.services)}</p><p class="tiny"><span class="gold">Equipamentos</span><br>${esc(g.equipment)}</p>${S.data.membership?.gym_id===g.id?badge('Sua unidade favorita','gold'):btn('Selecionar unidade','gym-favorite',g.id,'primary','star')}</div></article>`).join('')}</div>`;}

function profile(){const u=S.data.user;return pageHead('SUA IDENTIDADE. SUA JORNADA.','Meu perfil','Tudo o que faz parte da sua evolução.',btn('Sair','logout','','secondary','logout'))+`<div class="grid grid-2 profile-layout"><div><div class="card profile-card"><div class="profile-cover"><img src="assets/hero.png" alt="Identidade ATHEV"></div>${avatar(u,'avatar-lg')}<div class="profile-content"><h2>${esc(u.name)}</h2><small>${esc(u.email)}</small><div class="section-gap">${badge(u.role==='ALUNO'?'Membro ATHEV':u.role,'gold')}</div><div class="profile-stats"><div><strong>${u.weight?num(u.weight,1):'—'}</strong><small>PESO (KG)</small></div><div><strong>${u.height?num(u.height):'—'}</strong><small>ALTURA (CM)</small></div></div><p class="tiny muted">${esc(u.goal)} · ${esc(u.level)}</p>${btn('Editar perfil','profile-edit','','secondary','edit')}<div class="section-gap">${btn('Alterar foto','avatar','','ghost','upload')}</div></div></div><div class="card section-gap">${sectionHead('Sua academia')}${[...extraNav.filter(n=>n[0]!=='profile'),['achievements','trophy','Conquistas'],['library','book','Biblioteca'],['nutrition','food','Nutrição'],['assistant','spark','Assistente'],...(isTrainer()?[['trainer','users','Área do professor']]:[]),...(['RECEPCIONISTA','GERENTE','ADMIN'].includes(u.role)?[['admin','shield','Administração']]:[])].map(([r,i,l])=>`<a href="#${r}" class="settings-row"><span class="row">${icon(i)}${l}</span>${icon('right')}</a>`).join('')}</div></div><div class="stack"><div class="card">${sectionHead('Notificações',icon('bell'))}<p class="tiny muted">Avisos dentro do aplicativo, atualizados enquanto você o utiliza.</p>${[['treino','Treinos programados'],['aula','Aulas e reservas'],['avaliacao','Avaliações'],['mensalidade','Mensalidade'],['conquista','Conquistas'],['recorde','Recordes pessoais'],['meta','Meta semanal'],['inatividade','Lembrete de retorno']].map(([k,l])=>`<label class="settings-row"><span>${l}</span><input type="checkbox" class="toggle" data-preference="${k}" ${u.preferences[k]!==false?'checked':''} aria-label="${l}"></label>`).join('')}</div><div class="card">${sectionHead('Privacidade e conta',icon('shield'))}<div class="settings-row"><div><strong>Consentimento para tratamento dos dados</strong><small>Você pode gerenciar o consentimento ou solicitar a exclusão da conta.</small></div><input type="checkbox" class="toggle" id="consent-toggle" ${u.consent?'checked':''} aria-label="Consentimento"></div><div class="settings-row"><div><strong>Seus registros</strong><small>Exporte registros, medidas e histórico em JSON.</small></div>${iconBtn('download','export','','Exportar meus dados')}</div><div class="settings-row"><strong>Senha e segurança</strong>${btn('Alterar senha','password-open','','ghost','lock')}</div><div class="settings-row"><strong>Termos e privacidade</strong>${iconBtn('right','legal','','Ler termos e privacidade')}</div><div class="section-gap">${btn('Solicitar exclusão da conta','account-delete','','danger','trash')}</div></div></div></div>`;}

function notifications(){return pageHead('MANTENHA O FOCO','Notificações','O que importa na sua jornada.',btn('Marcar todas como lidas','notifications-read','','secondary','check'))+`<div class="card">${S.data.notifications.map(n=>`<article class="notification ${n.read?'':'unread'}"><div class="food-symbol">${icon(n.kind==='conquista'?'trophy':n.kind==='recorde'?'chart':'bell')}</div><div class="exercise-info"><strong>${esc(n.title)}</strong><p>${esc(n.body)}</p><small>${dateLabel(n.created_at)} · ${n.created_at.slice(11,16)}</small></div>${!n.read?iconBtn('check','notification-read',n.id,'Marcar como lida'):''}</article>`).join('')||empty('Tudo em dia','Seus próximos avisos aparecerão aqui.','bell')}</div>`;}

function assistantView(){return pageHead('INFORMAÇÃO PARA A SUA EVOLUÇÃO','Assistente ATHEV','Explore exercícios e entenda os seus registros.')+`<div class="notice" style="margin-bottom:18px">Assistente local com respostas por regras e consulta ao seu histórico. IA generativa não conectada.</div><div class="chat-box" id="chat-box"><div class="chat-message assistant">Olá, ${esc(S.data.user.name.split(' ')[0])}. Posso mostrar instruções, encontrar alternativas na biblioteca e consultar sua evolução de carga. Por onde começamos?</div>${S.messages.map(m=>`<div class="chat-message ${m.role}">${esc(m.text)}</div>`).join('')}</div><div class="suggestions">${['Como fazer supino reto?','Minha evolução no supino reto','Alternativas de agachamento livre'].map(q=>btn(esc(q),'ask-suggestion',q,'secondary')).join('')}</div><form class="chat-form" id="chat-form"><input class="input" name="message" placeholder="Pergunte sobre seu treino…" required maxlength="1200" aria-label="Mensagem para o assistente"><button class="btn btn-primary" aria-label="Enviar mensagem">${icon('arrow')}</button></form><p class="tiny muted section-gap">As respostas não substituem avaliação de um profissional e não fazem diagnósticos.</p>`;}

function trainer(){
 if(!isTrainer())return empty('Acesso restrito','Esta área é exclusiva de professores e gestores.','lock');
 if(S.student){const d=S.student;return `<div class="between" style="margin-bottom:22px">${btn('Meus alunos','student-back','','ghost','left')}<div class="row wrap">${btn('Agendar','student-schedule',d.user.id,'secondary','calendar')}${btn('Avaliação','measurement-student',d.user.id,'secondary','plus')}${btn('Criar treino','workout-student',d.user.id,'primary','dumbbell')}</div></div><div class="student-detail-head">${avatar(d.user,'avatar-lg')}<div><div class="eyebrow">ACOMPANHAMENTO INDIVIDUAL</div><h1 style="margin-bottom:6px">${esc(d.user.name)}</h1><small>${esc(d.user.goal)} · ${esc(d.user.level)}</small></div></div><div class="grid grid-4 stat-cards">${stat('Treinos totais',d.stats.total,'','dumbbell','Sessões concluídas')}${stat('Na semana',d.stats.week,'','calendar','Frequência semanal')}${stat('Peso atual',d.user.weight?num(d.user.weight,1):'—','kg','weight','Último registro')}${stat('Recordes',d.stats.records,'','trophy','Exercícios com recorde')}</div><h2 class="section-title">Fichas do aluno</h2><div class="grid grid-2">${d.workouts.map(w=>workoutCard(w,true)).join('')}</div>${!d.workouts.length?empty('Nenhum treino cadastrado','Crie uma ficha para este aluno.','dumbbell'):''}<div class="grid grid-2 section-gap"><div class="card">${sectionHead('Evolução corporal')}${chart(d.measurements.filter(m=>m.weight).map(m=>({date:m.date,value:m.weight})))}</div><div class="card">${sectionHead('Observações',btn('Adicionar','trainer-note',d.user.id,'ghost','plus'))}${d.notes.map(n=>`<div class="settings-row"><div><p class="tiny" style="margin:0 0 6px">${esc(n.body)}</p><small>${esc(n.trainer_name)} · ${dateLabel(n.created_at)}</small></div></div>`).join('')||'<p class="tiny muted">Nenhuma observação registrada.</p>'}</div></div><div class="card section-gap">${sectionHead('Histórico de treino')}<div class="table-wrap"><table><thead><tr><th>Data</th><th>Treino</th><th>Duração</th><th>Séries</th><th>Volume</th><th></th></tr></thead><tbody>${d.history.map(h=>`<tr><td>${dateLabel(h.started_at)}</td><td>${esc(h.name)}</td><td>${duration(h.duration)}</td><td>${h.summary.sets}</td><td>${num(h.summary.volume)} kg</td><td>${btn('Ver','student-history',h.id,'ghost','right')}</td></tr>`).join('')}</tbody></table></div></div>`;}
 const list=S.students.filter(u=>normalize(u.name+' '+u.email).includes(normalize(S.studentSearch||'')));
 return pageHead('ORIENTE. ACOMPANHE. TRANSFORME.','Área do professor','Uma visão clara de cada jornada.',btn('Criar template','template-new','','primary','plus'))+`<div class="toolbar"><div class="search-box">${icon('search')}<input class="input" data-search="students" value="${esc(S.studentSearch||'')}" placeholder="Buscar aluno" aria-label="Buscar aluno"></div>${badge(S.students.length+' alunos vinculados','gold')}</div><div class="grid grid-2">${list.map(u=>`<div class="card student-card">${avatar(u)}<div class="exercise-info"><strong>${esc(u.name)}</strong><small>${esc(u.goal||'Objetivo não informado')} · ${esc(u.level||'')}</small></div>${iconBtn('right','student-open',u.id,'Ver aluno')}</div>`).join('')}</div>${!list.length?empty('Nenhum aluno encontrado','A administração pode vincular alunos ao seu perfil.','users'):''}<h2 class="section-title">Templates de treino</h2><div class="grid grid-2">${S.templates.map(w=>`<article class="card"><div class="between"><h3>${esc(w.name)}</h3>${iconBtn('edit','workout-edit',w.id,'Editar template')}</div><p class="tiny muted">${esc(w.muscle)} · ${w.items.length} exercícios</p>${btn('Atribuir a um aluno','template-assign',w.id,'secondary','copy')}</article>`).join('')}</div>`;
}

export function admin(){
 if(!S.staff)return empty('Carregando painel','Aguarde um momento.','shield');const d=S.staff,manager=isManager(),s=S.adminSection;
 const sections=manager?[['dashboard','Dashboard'],['alunos','Alunos'],['professores','Professores'],['unidades','Unidades'],['planos','Planos'],['financeiro','Financeiro'],['aulas','Aulas'],['treinos','Treinos'],['exercicios','Exercícios'],['acessos','Acessos'],['notificacoes','Notificações'],['relatorios','Relatórios'],['configuracoes','Configurações']]:[['acessos','Acessos'],['alunos','Alunos'],['aulas','Aulas']];
 const table=(heads,body)=>`<div class="card"><div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div></div>`;
 let body='';
 if(s==='dashboard'&&manager){let students=d.users.filter(u=>u.role==='ALUNO'),paid=d.payments.filter(p=>p.status==='Pago'),pending=d.payments.filter(p=>p.status==='Pendente'),overdue=pending.filter(p=>p.due_date<dateISO());const revenue={};paid.forEach(p=>{const key=p.paid_at?.slice(0,10)||p.due_date;revenue[key]=(revenue[key]||0)+p.amount;});body=`<div class="grid grid-4 stat-cards">${stat('Alunos ativos',students.filter(u=>u.active&&u.status==='Ativo').length,'','users','Cadastro e plano ativos')}${stat('Receita simulada',money(paid.reduce((a,p)=>a+p.amount,0)),'','wallet','Faturas marcadas como pagas')}${stat('Faturas vencidas',overdue.length,'','receipt',money(overdue.reduce((a,p)=>a+p.amount,0))+' em aberto')}${stat('Check-ins hoje',d.checkins.filter(c=>c.created_at.startsWith(dateISO())).length,'','qr','Validações demonstrativas')}</div><div class="grid grid-2"><div class="card">${sectionHead('Recebimentos demonstrativos')}${chart(Object.entries(revenue).sort().map(([date,value])=>({date,value})),'R$')}</div><div class="card">${sectionHead('Visão da operação')}<div class="settings-row"><span>Novos alunos neste mês</span><strong class="gold">${students.filter(u=>u.created_at.startsWith(dateISO().slice(0,7))).length}</strong></div><div class="settings-row"><span>Solicitações de cancelamento</span><strong class="gold">${students.filter(u=>u.cancel_requested).length}</strong></div><div class="settings-row"><span>Planos cancelados</span><strong>${students.filter(u=>u.status==='Cancelado').length}</strong></div><div class="settings-row"><span>Aulas hoje</span><strong>${d.classes.filter(c=>c.starts_at.startsWith(dateISO())).length}</strong></div><div class="settings-row"><span>Alunos treinando agora</span><small>Dados indisponíveis</small></div></div></div>`;}
 else if(s==='alunos'||s==='professores'){
 let users=manager?d.users.filter(u=>s==='alunos'?u.role==='ALUNO':u.role!=='ALUNO'):S.students;
 users=users.filter(u=>normalize(u.name+' '+u.email).includes(normalize(S.adminSearch||''))&&(!S.adminStatus||String(u.active)===S.adminStatus));
 body=`<div class="toolbar"><div class="search-box">${icon('search')}<input class="input" data-search="admin" value="${esc(S.adminSearch||'')}" placeholder="Pesquisar nome ou e-mail" aria-label="Pesquisar usuários"></div><select id="admin-status" style="max-width:160px"><option value="">Todos os status</option><option value="1" ${S.adminStatus==='1'?'selected':''}>Ativos</option><option value="0" ${S.adminStatus==='0'?'selected':''}>Bloqueados</option></select>${manager?btn('Novo cadastro','admin-user-new',s==='alunos'?'ALUNO':'PROFESSOR','primary','plus'):''}</div>`+table(['Nome','E-mail','Perfil','Status','Ações'],users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${esc(u.role||'ALUNO')}</td><td>${badge(u.active?'Ativo':'Bloqueado',u.active?'green':'red')}${u.cancel_requested?' '+badge('Cancelamento solicitado','gold'):''}</td><td><div class="row">${manager?iconBtn('edit','admin-user-edit',u.id,'Editar usuário'):''}${manager&&u.role==='ALUNO'?iconBtn('chart','student-open',u.id,'Ver histórico e treino'):''}${manager?btn(u.active?'Bloquear':'Desbloquear','admin-block',u.id,'ghost'):''}</div></td></tr>`).join(''));
 }else if(s==='unidades')body=`<div class="toolbar">${btn('Nova unidade','entity-new','gyms','primary','plus')}</div>`+table(['Unidade','Endereço','Horários',''],d.gyms.map(g=>`<tr><td>${esc(g.name)}</td><td>${esc(g.address)}</td><td>${esc(g.hours)}</td><td>${iconBtn('edit','entity-edit','gyms:'+g.id,'Editar unidade')}</td></tr>`).join(''));
 else if(s==='planos')body=`<div class="toolbar">${btn('Novo plano','entity-new','plans','primary','plus')}</div>`+table(['Plano','Mensalidade demonstrativa','Benefícios',''],d.plans.map(p=>`<tr><td>${esc(p.name)}</td><td>${money(p.price)}</td><td>${esc(p.benefits.replaceAll('|',' · '))}</td><td>${iconBtn('edit','entity-edit','plans:'+p.id,'Editar plano')}</td></tr>`).join(''));
 else if(s==='financeiro')body=`<div class="notice" style="margin-bottom:20px">Valores de demonstração. Este painel não processa cobranças reais.</div><div class="toolbar">${btn('Emitir fatura local','invoice-new','','primary','plus')}${btn('Exportar CSV','report','payments','secondary','download')}</div>`+table(['Aluno','Vencimento','Valor','Status','Tipo'],d.payments.map(p=>`<tr><td>${esc(p.name)}</td><td>${dateLabel(p.due_date)}</td><td>${money(p.amount)}</td><td>${badge(p.status,p.status==='Pago'?'green':'gold')}</td><td>Demonstração</td></tr>`).join(''));
 else if(s==='aulas')body=`<div class="toolbar">${manager?btn('Nova aula','entity-new','classes','primary','plus'):''}</div>`+table(['Aula','Data','Professor','Vagas',''],d.classes.map(c=>`<tr><td>${esc(c.title)}</td><td>${dateLabel(c.starts_at)} · ${c.starts_at.slice(11,16)}</td><td>${esc(c.teacher)}</td><td>${c.capacity-c.reserved} / ${c.capacity}</td><td>${manager?`<div class="row">${iconBtn('edit','entity-edit','classes:'+c.id,'Editar aula')}${iconBtn('trash','class-delete',c.id,'Excluir aula')}</div>`:''}</td></tr>`).join(''));
 else if(s==='treinos')body=`<div class="card"><h2>Gestão de fichas e templates</h2><p class="muted">Selecione um aluno para criar, editar ou duplicar treinos e acompanhar o histórico.</p><a class="btn btn-primary" href="#trainer">Abrir área de acompanhamento ${icon('arrow')}</a></div>`;
 else if(s==='exercicios')body=`<div class="toolbar">${btn('Novo exercício','entity-new','exercises','primary','plus')}</div>`+table(['Exercício','Grupo','Equipamento',''],S.data.exercises.map(e=>`<tr><td>${esc(e.name)}</td><td>${esc(e.muscle)}</td><td>${esc(e.equipment)}</td><td>${iconBtn('edit','entity-edit','exercises:'+e.id,'Editar exercício')}</td></tr>`).join(''));
 else if(s==='acessos')body=`<div class="grid grid-2"><div class="card"><div class="eyebrow">RECEPÇÃO</div><h2>Validar acesso</h2><p class="tiny muted">Use um leitor de QR que digita o conteúdo no campo abaixo, ou cole o token exibido na carteira do aluno.</p><form id="checkin-form">${field('Token de uso único','token','','text','required autocomplete="off" placeholder="Leia ou cole o token"')}<p class="form-error" role="alert"></p><button class="btn btn-primary">${icon('qr')}Validar token</button></form></div><div class="notice">Validação funcional no banco do ATHEV. O acionamento de catraca física e a leitura por câmera não estão conectados nesta versão.</div></div><div class="section-gap">${table(['Aluno','Horário','Tipo'],d.checkins.map(c=>`<tr><td>${esc(c.name)}</td><td>${dateLabel(c.created_at)} · ${c.created_at.slice(11,16)}</td><td>Validação local</td></tr>`).join(''))}</div>`;
 else if(s==='notificacoes')body=`<div class="card"><h2>Enviar aviso no aplicativo</h2><form id="admin-notification-form">${select('Destinatário','user_id',[['','Todos os usuários ativos'],...d.users.map(u=>[u.id,u.name])])}${field('Título','title','','text','required maxlength="100"')}${textarea('Mensagem','body','','required maxlength="1000"')}<p class="tiny muted">O aviso aparece na central de notificações, conforme a preferência de treinos de cada usuário.</p><p class="form-error" role="alert"></p><button class="btn btn-primary">Enviar aviso interno ${icon('bell')}</button></form></div>`;
 else if(s==='relatorios')body=`<div class="grid grid-3">${[['users','Cadastros','users'],['payments','Financeiro','wallet'],['checkins','Acessos','qr']].map(([k,l,i])=>`<div class="card">${icon(i)}<h3 class="section-gap">${l}</h3><p class="tiny muted">Exporte os registros atuais em CSV.</p>${btn('Baixar relatório','report',k,'secondary','download')}</div>`).join('')}</div><h2 class="section-title">Registro de ações administrativas</h2>`+table(['Data','Responsável','Ação','Registro'],d.audit.map(a=>`<tr><td>${dateLabel(a.created_at)} ${a.created_at.slice(11,16)}</td><td>${esc(a.actor_name||'Conta excluída')}</td><td>${esc(a.action)}</td><td>${esc(a.target_type)} ${a.target_id||''}</td></tr>`).join(''));
 else body=`<div class="card"><h2>Configurações da operação</h2><div class="settings-row"><div><strong>Banco de dados</strong><small>Supabase · PostgreSQL</small></div>${badge('Conectado','green')}</div><div class="settings-row"><div><strong>Pagamentos e catraca</strong><small>Integrações externas não configuradas</small></div>${badge('Demonstração','gold')}</div><div class="settings-row"><div><strong>Assistente</strong><small>Biblioteca e histórico com respostas por regras</small></div>${badge('Local','gold')}</div><div class="settings-row"><div><strong>Cancelamento de aula</strong><small>O prazo é configurado individualmente no cadastro da aula.</small></div>${btn('Gerenciar aulas','admin-section','aulas','ghost','calendar')}</div><div class="settings-row"><div><strong>Perfis e permissões</strong><small>Aluno, professor, recepção, gerência e administração.</small></div>${btn('Gerenciar equipe','admin-section','professores','ghost','users')}</div></div>`;
 return pageHead('ATHEV · GESTÃO DA ACADEMIA',manager?'Painel administrativo':'Recepção','Uma visão organizada da sua operação.')+`<div class="staff-tabs">${sections.map(([k,l])=>`<button class="btn btn-secondary ${s===k?'active':''}" data-action="admin-section" data-id="${k}">${l}</button>`).join('')}</div>${body}`;
}

export function view(){return ({home,workouts,library,session,evolution,agenda,nutrition,achievements,wallet,plans,units,profile,notifications,assistant:assistantView,trainer,admin}[S.route]||home)();}
